from math import ceil
from time import sleep
from taf.transport.ssh import ssh

from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output


class TestPc:
    def __init__(self, hostname, username, password):
        self.test_pc = ssh()
        self.test_pc_alias = 'UEPC'
        self.test_pc.connect_to(hostname=hostname,
                                username=username,
                                password=password,
                                alias=self.test_pc_alias)

    def __del__(self):
        self.test_pc.disconnect(connection=self.test_pc_alias)

    def lock(self, ue_lock_file_name, timeout_sec, sleep_between_tries_sec):
        """
        Waiting for ue and create .lock file.
        :param ue_lock_file_name: name of lock file related to ue
        :type ue_lock_file_name: str
        :param timeout_sec: Waiting time for ue to be available [in seconds]
        :type timeout_sec: int
        :param sleep_between_tries_sec: Waiting time between tries [in seconds]
        :type sleep_between_tries_sec: int
        :raises ValueError exception when there is file reading error
        :raises EnvironmentError when there is not ue available
        """
        try:
            self._wait_for_ue_to_be_available(self._get_ue_log_file_path(ue_lock_file_name),
                                              int(timeout_sec),
                                              int(sleep_between_tries_sec))
            self.test_pc.execute(command='touch {}'.format(self._get_ue_log_file_path(ue_lock_file_name)),
                                 connection=self.test_pc_alias)
        except ValueError:
            raise ValueError("Failed to lock UE")

    def unlock(self, ue_lock_file_name):
        """
        Remove .lock file.
        :param ue_lock_file_name: name of lock file related to ue
        :type ue_lock_file_name: str
        :raises ValueError exception while executing removal command
        """
        try:
            self.test_pc.execute(command='rm {}'.format(self._get_ue_log_file_path(ue_lock_file_name)),
                                 connection=self.test_pc_alias)
        except ValueError:
            raise ValueError("Failed to unlock UE")

    def reboot(self):
        """
        Execute reboot command
        :raises ValueError exception while executing removal command
        """
        try:
            self.test_pc.execute(command='nohup adb.exe reboot', connection=self.test_pc_alias)
        except ValueError:
            raise ValueError("Failed to reboot UE")

    @log_input_and_output
    def _get_ue_log_file_path(self, ue_lock_file_name):
        """
        Create full lock file path based on provided: ue_lock_file_name.
        :param ue_lock_file_name: name of lock file related to ue
        :type ue_lock_file_name: str
        :return: full lock file path
        :type: str
        """
        return '/etc/{}.lock'.format(ue_lock_file_name)

    def _wait_for_ue_to_be_available(self, ue_file_lock, timeout_sec, sleep_between_tries_sec):
        """
        Waiting for UE release for selected period of timeout.
        :param ue_file_lock: Full path to ue lock file
        :type ue_file_lock: str
        :param timeout_sec: Waiting time for UE to be available [in seconds]
        :type timeout_sec: int
        :param sleep_between_tries_sec: Waiting time between tries [in seconds]
        :type sleep_between_tries_sec: int
        :return: True while there is no .lock file, UE is available
        :rtype: bool
        :raises ValueError exception when there is file reading error
        :raises EnvironmentError when there is no UE available
        """
        for _ in range(int(ceil(timeout_sec / sleep_between_tries_sec))):
            try:
                if not self.test_pc.file_exists(remote_path=ue_file_lock, connection=self.test_pc_alias):
                    return True
            except ValueError:
                raise ValueError("File exists reading error")
            sleep(sleep_between_tries_sec)
        raise EnvironmentError('UE is not available, waiting time elapsed: {} sec'.format(timeout_sec))
